import{_ as i,I as n,c as r,o as s,j as t,J as o,a5 as d,a as l}from"./chunks/framework.CUJoMJm2.js";const f=JSON.parse('{"title":"Protocols","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/index.md","filePath":"protocols/index.md","lastUpdated":1768070912000}'),c={name:"protocols/index.md"};function p(h,e,m,u,b,g){const a=n("CopyOrDownloadAsMarkdownButtons");return s(),r("div",null,[e[0]||(e[0]=t("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /protocols.md for this page in Markdown format",-1)),e[1]||(e[1]=t("h1",{id:"protocols",tabindex:"-1"},[l("Protocols "),t("a",{class:"header-anchor",href:"#protocols","aria-label":"Permalink to “Protocols”"},"​")],-1)),o(a),e[2]||(e[2]=d(`<p>Sideband is a layered communication stack for browser-to-daemon communication, designed to work reliably behind NAT with end-to-end encryption.</p><blockquote><p>These specifications are implementation-neutral. You may implement them in any language or runtime, including proprietary systems, under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a> terms.</p></blockquote><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><p><strong>Start here</strong>: <a href="./architecture">Protocol Architecture</a> defines layering, frame wrapping rules, and dependency invariants. All specifications below must be consistent with the architecture document.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌───────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Application / SDK                                 │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ RPC (semantic envelopes inside MessageFrame.data) │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ SBP (application framing, routing, correlation)   │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Session: SBRP (relay E2EE) or SBDP (direct P2P)   │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Transport (WebSocket, WebRTC, etc.)               │</span></span>
<span class="line"><span>└───────────────────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Layer</th><th>Protocol</th><th>Status</th><th>Purpose</th></tr></thead><tbody><tr><td>App Framing</td><td>SBP</td><td>v1</td><td>Framing, multiplexing, message routing</td></tr><tr><td>Relay Session</td><td>SBRP</td><td>Draft</td><td>E2EE sessions via relay server</td></tr><tr><td>Direct Session</td><td>SBDP</td><td>Design</td><td>P2P encryption (future)</td></tr><tr><td>Semantic</td><td>RPC</td><td>v1</td><td>Typed request/response patterns</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>RPC envelopes live inside <code>MessageFrame.data</code>. Session layers (SBRP/SBDP) encrypt entire SBP frames; they never inspect RPC content. See <a href="./architecture">architecture</a> for wrapping rules.</p></div><h2 id="sbp-sideband-protocol" tabindex="-1">SBP (Sideband Protocol) <a class="header-anchor" href="#sbp-sideband-protocol" aria-label="Permalink to “SBP (Sideband Protocol)”">​</a></h2><p>Topology-agnostic framing used by all session layers. Defines frame types, message routing, and wire format.</p><p><a href="./sbp/">Read the SBP specification →</a></p><h2 id="sbrp-sideband-relay-protocol" tabindex="-1">SBRP (Sideband Relay Protocol) <a class="header-anchor" href="#sbrp-sideband-relay-protocol" aria-label="Permalink to “SBRP (Sideband Relay Protocol)”">​</a></h2><p>Default transport: secure, relay-based sessions with E2EE. The relay never sees plaintext.</p><p><a href="./sbrp/">Read the SBRP specification →</a></p><h2 id="sbdp-sideband-direct-protocol" tabindex="-1">SBDP (Sideband Direct Protocol) <a class="header-anchor" href="#sbdp-sideband-direct-protocol" aria-label="Permalink to “SBDP (Sideband Direct Protocol)”">​</a></h2><p>Future: direct P2P when both peers can establish a connection without relay.</p><p><a href="./sbdp/">Read the SBDP specification →</a></p><h2 id="rpc" tabindex="-1">RPC <a class="header-anchor" href="#rpc" aria-label="Permalink to “RPC”">​</a></h2><p>Typed request/response/notification semantics inside SBP message frames.</p><p><a href="./rpc/">Read the RPC specification →</a></p><h2 id="standard-documentation-pattern" tabindex="-1">Standard Documentation Pattern <a class="header-anchor" href="#standard-documentation-pattern" aria-label="Permalink to “Standard Documentation Pattern”">​</a></h2><p>Every Sideband protocol MUST contain these documents:</p><table tabindex="0"><thead><tr><th>Document</th><th>Purpose</th><th>Authority</th><th>Required</th></tr></thead><tbody><tr><td><code>index.md</code></td><td>Overview, intent, roles, delegation, authority table</td><td>Navigation only</td><td>Yes</td></tr><tr><td><code>wire-format.md</code> or <code>cryptography-and-wire.md</code></td><td>On-wire encoding, frame structure</td><td>Primary for encoding</td><td>Yes</td></tr><tr><td><code>behavior.md</code> or <code>state-machine.md</code></td><td>Runtime semantics, state transitions</td><td>Primary for behavior</td><td>Yes</td></tr><tr><td><code>errors.md</code></td><td>Error taxonomy, codes, retryability</td><td>Primary for errors</td><td>Conditional*</td></tr><tr><td><code>conformance.md</code></td><td>Testable invariants, test vectors</td><td>Test specification</td><td>Yes</td></tr></tbody></table><p>*<code>errors.md</code> is required unless errors are fully delegated to a parent protocol via explicit statement in <code>index.md</code>.</p><p><strong>Deviations</strong>: Any deviation from this pattern MUST be documented in the protocol&#39;s <code>index.md</code> with rationale.</p><h3 id="authority-model" tabindex="-1">Authority Model <a class="header-anchor" href="#authority-model" aria-label="Permalink to “Authority Model”">​</a></h3><p>Documents have two authority levels:</p><ul><li><strong>Primary</strong>: Defines canonical rules. Source of truth.</li><li><strong>Supporting</strong>: May reference and elaborate, but MUST NOT redefine.</li></ul><p>When documents conflict:</p><ol><li><strong>Same protocol</strong>: Primary authority wins</li><li><strong>Cross-protocol</strong>: architecture.md governs layer boundaries; lower-layer protocol is authoritative</li><li><strong>Unresolved</strong>: File an issue; do not ship conflicting specs</li></ol><h3 id="authority-banners" tabindex="-1">Authority Banners <a class="header-anchor" href="#authority-banners" aria-label="Permalink to “Authority Banners”">​</a></h3><p>Every protocol document MUST include an authority banner after the title:</p><div class="language-markdown"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Wire Format</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Authority**</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">: Primary (Normative)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Purpose**</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">: Defines on-wire encoding for SBRP.</span></span></code></pre></div><h2 id="pattern-compliance-checklist" tabindex="-1">Pattern Compliance Checklist <a class="header-anchor" href="#pattern-compliance-checklist" aria-label="Permalink to “Pattern Compliance Checklist”">​</a></h2><p>For each protocol, verify:</p><ul><li>[ ] index.md has delegation section</li><li>[ ] index.md has authority table</li><li>[ ] index.md has recommended reading order</li><li>[ ] index.md contains no RFC 2119 keywords</li><li>[ ] All documents have authority banners with purpose line</li><li>[ ] Deviations from pattern are documented with rationale</li><li>[ ] Stubs have status banner (no RFC 2119 keywords)</li></ul>`,35))])}const k=i(c,[["render",p]]);export{f as __pageData,k as default};
